-- Smart Rental production-like seed dataset (Supabase/PostgreSQL)
-- Generated at 2026-05-14
-- Offset mode: id = base_id + snapshot(MAX(id)) captured once at import time
BEGIN;

-- Stable offset snapshot (must be created once before any insert)
CREATE TEMP TABLE __seed_offsets AS
SELECT
  COALESCE((SELECT MAX(id) FROM users), 0) AS users_off,
  COALESCE((SELECT MAX(id) FROM vip_subscriptions), 0) AS vip_off,
  COALESCE((SELECT MAX(id) FROM properties), 0) AS prop_off,
  COALESCE((SELECT MAX(id) FROM rooms), 0) AS room_off,
  COALESCE((SELECT MAX(id) FROM appointments), 0) AS appt_off,
  COALESCE((SELECT MAX(id) FROM contracts), 0) AS contract_off,
  COALESCE((SELECT MAX(id) FROM bills), 0) AS bill_off,
  COALESCE((SELECT MAX(id) FROM reviews), 0) AS review_off,
  COALESCE((SELECT MAX(id) FROM room_reports), 0) AS report_off,
  COALESCE((SELECT MAX(id) FROM notifications), 0) AS notif_off;

-- =====================================================
-- USERS (40): 2 admins, 8 landlords, 30 tenants
-- =====================================================
INSERT INTO users (
    id, username, password, full_name, email, current_address, date_of_birth, phone_number, zalo_phone, wallet_address, bank_name, bank_account_number, bank_account_holder, bank_qr_url, avatar_url, cccd_number, cccd_images, kyc_metadata, kyc_status, kyc_note, reputation_score, role, created_at, updated_at, cccd_front_url, cccd_back_url, kyc_attempts, is_locked, locked_at, lock_until, lock_reason, verification_code, verification_expiry, is_enabled
)
SELECT
    v.id + __off.users_off AS id,
    CASE WHEN __off.users_off = 0 THEN v.username ELSE v.username || '.r' || __off.users_off::text END AS username,
    v.password,
    v.full_name,
    CASE WHEN __off.users_off = 0 THEN v.email ELSE split_part(v.email, '@', 1) || '.r' || __off.users_off::text || '@' || split_part(v.email, '@', 2) END AS email,
    v.current_address,
    v.date_of_birth::date,
    v.phone_number,
    v.zalo_phone,
    v.wallet_address,
    v.bank_name,
    v.bank_account_number,
    v.bank_account_holder,
    v.bank_qr_url,
    v.avatar_url,
    v.cccd_number,
    v.cccd_images,
    v.kyc_metadata,
    v.kyc_status,
    v.kyc_note,
    v.reputation_score,
    v.role,
    v.created_at::timestamp,
    v.updated_at::timestamp,
    v.cccd_front_url,
    v.cccd_back_url,
    v.kyc_attempts,
    v.is_locked,
    v.locked_at::timestamp,
    v.lock_until::timestamp,
    v.lock_reason,
    v.verification_code,
    v.verification_expiry::timestamp,
    v.is_enabled
