-- =====================================================
-- NOTIFICATIONS (80)
-- =====================================================
INSERT INTO notifications (
    id, user_id, title, message, type, reference_id, is_read, created_at
)
SELECT
    v.id + __off.notif_off AS id,
    v.user_id + __off.users_off AS user_id,
    v.title,
    v.message,
    v.type,
    CASE
      WHEN v.reference_id IS NULL THEN NULL
      WHEN v.type IN ('PAYMENT_REMINDER', 'BILL_CREATED') THEN v.reference_id + __off.bill_off
      WHEN v.type IN ('CONTRACT_UPDATE', 'NEW_REVIEW') THEN v.reference_id + __off.contract_off
      WHEN v.type = 'APPOINTMENT_UPDATE' THEN v.reference_id + __off.appt_off
      WHEN v.type IN ('PROPERTY_APPROVED', 'PROPERTY_REJECTED') THEN v.reference_id + __off.prop_off
      WHEN v.type IN ('ROOM_AVAILABLE', 'ROOM_APPROVED', 'ROOM_REJECTED', 'ROOM_UPDATED') THEN v.reference_id + __off.room_off
      ELSE v.reference_id
    END AS reference_id,
    v.is_read,
    v.created_at::timestamp
FROM (VALUES
(1, 1, 'Thông báo hệ thống', 'Hệ thống đã tối ưu trải nghiệm và cập nhật một số tính năng bảo mật.', 'SYSTEM', NULL, FALSE, '2026-04-16 04:54:00'),
(2, 2, 'Nhắc thanh toán hóa đơn', 'Bạn có hóa đơn gần đến hạn hoặc đã quá hạn, vui lòng kiểm tra để tránh phát sinh phí phạt.', 'PAYMENT_REMINDER', 2, TRUE, '2026-04-24 14:27:00'),
(3, 3, 'Cập nhật hợp đồng', 'Hợp đồng của bạn có thay đổi mới, vui lòng mở chi tiết để xác nhận.', 'CONTRACT_UPDATE', 3, TRUE, '2026-02-18 17:16:00'),
