-- Reset sequences after explicit IDs
SELECT setval(pg_get_serial_sequence('users','id'), COALESCE((SELECT MAX(id) FROM users), 1), true);
SELECT setval(pg_get_serial_sequence('vip_subscriptions','id'), COALESCE((SELECT MAX(id) FROM vip_subscriptions), 1), true);
SELECT setval(pg_get_serial_sequence('properties','id'), COALESCE((SELECT MAX(id) FROM properties), 1), true);
SELECT setval(pg_get_serial_sequence('rooms','id'), COALESCE((SELECT MAX(id) FROM rooms), 1), true);
SELECT setval(pg_get_serial_sequence('appointments','id'), COALESCE((SELECT MAX(id) FROM appointments), 1), true);
SELECT setval(pg_get_serial_sequence('contracts','id'), COALESCE((SELECT MAX(id) FROM contracts), 1), true);
SELECT setval(pg_get_serial_sequence('bills','id'), COALESCE((SELECT MAX(id) FROM bills), 1), true);
SELECT setval(pg_get_serial_sequence('reviews','id'), COALESCE((SELECT MAX(id) FROM reviews), 1), true);
SELECT setval(pg_get_serial_sequence('room_reports','id'), COALESCE((SELECT MAX(id) FROM room_reports), 1), true);
SELECT setval(pg_get_serial_sequence('notifications','id'), COALESCE((SELECT MAX(id) FROM notifications), 1), true);

COMMIT;